def hex_to_bits(hex_str):
    # Remove spaces and convert to binary string
    hex_str = hex_str.replace(" ", "")
    return bin(int(hex_str, 16))[2:].zfill(len(hex_str) * 4)

def compare_puf(resp1, resp2):
    bits1 = hex_to_bits(resp1)
    bits2 = hex_to_bits(resp2)

    # print(bits1)
    # Ensure same length (truncate longer one if needed)
    min_len = min(len(bits1), len(bits2))
    bits1, bits2 = bits1[:min_len], bits2[:min_len]

    matches = [i for i in range(min_len) if bits1[i] == bits2[i]]
    mismatches = [i for i in range(min_len) if bits1[i] != bits2[i]]

    print(f"Total bits compared: {min_len}")
    print(f"Matches: {len(matches)}")
    print(f"Mismatches: {len(mismatches)}")
    print(f"Bit agreement: {len(matches)/min_len:.2%}")

    return matches, mismatches

